package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
	"sort"
)

type trackGroup struct {
	SourceIP          string
	EventCount        int
	MaxEnrichedRisk   float64
	ThreatTypes       []string
	ThreatActors      []string
	FirstActivity     string
	LastActivity      string
}

type trackOutput struct {
	SourceIP        string   `json:"source_ip"`
	EventCount      int      `json:"event_count"`
	MaxEnrichedRisk float64  `json:"max_enriched_risk"`
	ThreatTypes     []string `json:"threat_types"`
	ThreatActors    []string `json:"threat_actors"`
	FirstActivity   string   `json:"first_activity"`
	LastActivity    string   `json:"last_activity"`
	ThreatLevel    string   `json:"threat_level"`
}

func runTrack(args []string) int {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024*1024), 16*1024*1024)

	groups := make(map[string]*trackGroup)
	lineNo := 0

	for scanner.Scan() {
		lineNo++
		line := scanner.Text()
		if line == "" {
			continue
		}

		var ev map[string]interface{}
		if err := json.Unmarshal([]byte(line), &ev); err != nil {
			fmt.Fprintf(os.Stderr, "line %d: invalid JSON: %v\n", lineNo, err)
			return 2
		}

		sourceIP := trackGetString(ev, "source_ip", "")
		g, ok := groups[sourceIP]
		if !ok {
			g = &trackGroup{
				SourceIP:        sourceIP,
				MaxEnrichedRisk: -1,
				ThreatTypes:     []string{},
				ThreatActors:    []string{},
			}
			groups[sourceIP] = g
		}

		g.EventCount++

		if risk, ok := trackGetFloat(ev, "enriched_risk_score"); ok && risk > g.MaxEnrichedRisk {
			g.MaxEnrichedRisk = risk
		}

		if threatType, ok := trackGetStringOk(ev, "threat_type"); ok {
			g.ThreatTypes = append(g.ThreatTypes, threatType)
		}

		if actors, ok := trackGetStringSlice(ev, "threat_actors"); ok {
			g.ThreatActors = append(g.ThreatActors, actors...)
		}

		firstSeen := trackGetString(ev, "first_seen", "")
		if g.FirstActivity == "" || firstSeen < g.FirstActivity {
			g.FirstActivity = firstSeen
		}

		lastSeen := trackGetString(ev, "last_seen", "")
		if lastSeen > g.LastActivity {
			g.LastActivity = lastSeen
		}
	}

	if err := scanner.Err(); err != nil {
		fmt.Fprintf(os.Stderr, "error reading input: %v\n", err)
		return 2
	}

	outputs := make([]trackOutput, 0, len(groups))
	for _, g := range groups {
		if g.MaxEnrichedRisk < 0 {
			g.MaxEnrichedRisk = 0
		}
		outputs = append(outputs, trackOutput{
			SourceIP:        g.SourceIP,
			EventCount:      g.EventCount,
			MaxEnrichedRisk: g.MaxEnrichedRisk,
			ThreatTypes:     ensureStringSlice(uniqueSortedStrings(g.ThreatTypes)),
			ThreatActors:    ensureStringSlice(uniqueSortedStrings(g.ThreatActors)),
			FirstActivity:   g.FirstActivity,
			LastActivity:    g.LastActivity,
			ThreatLevel:     trackThreatLevel(g.EventCount, g.MaxEnrichedRisk),
		})
	}

	sort.SliceStable(outputs, func(i, j int) bool {
		if outputs[i].MaxEnrichedRisk != outputs[j].MaxEnrichedRisk {
			return outputs[i].MaxEnrichedRisk > outputs[j].MaxEnrichedRisk
		}
		return outputs[i].SourceIP < outputs[j].SourceIP
	})

	for _, out := range outputs {
		b, err := json.Marshal(out)
		if err != nil {
			fmt.Fprintf(os.Stderr, "error encoding output: %v\n", err)
			return 2
		}
		fmt.Println(string(b))
	}

	return 0
}

func trackThreatLevel(eventCount int, maxRisk float64) string {
	if eventCount >= 5 || maxRisk >= 500.0 {
		return "critical"
	}
	if eventCount >= 3 || maxRisk >= 300.0 {
		return "high"
	}
	if eventCount >= 2 || maxRisk >= 150.0 {
		return "medium"
	}
	return "low"
}

func ensureStringSlice(s []string) []string {
	if s == nil {
		return []string{}
	}
	return s
}

func trackGetString(ev map[string]interface{}, key, fallback string) string {
	if v, ok := ev[key].(string); ok {
		return v
	}
	return fallback
}

func trackGetStringOk(ev map[string]interface{}, key string) (string, bool) {
	v, ok := ev[key].(string)
	return v, ok
}

func trackGetFloat(ev map[string]interface{}, key string) (float64, bool) {
	switch v := ev[key].(type) {
	case float64:
		return v, true
	case int:
		return float64(v), true
	case int64:
		return float64(v), true
	}
	return 0, false
}

func trackGetStringSlice(ev map[string]interface{}, key string) ([]string, bool) {
	arr, ok := ev[key].([]interface{})
	if !ok {
		return nil, false
	}
	out := make([]string, 0, len(arr))
	for _, item := range arr {
		if s, ok := item.(string); ok {
			out = append(out, s)
		}
	}
	return out, true
}
